function App() {
  const [role, setRole] = useState(null);
  const [maids, setMaids] = useState([]);
  const [showMaids, setShowMaids] = useState(false);

  const handleFindHouseHelp = async () => {
    setShowMaids(true);
    try {
      const response = await fetch('http://localhost:5000/api/maids');
      const data = await response.json();
      setMaids(data.maids || []);
    } catch (error) {
      setMaids([]);
      alert('Failed to fetch maids.');
    }
  };

  return (
    <Container maxWidth="sm" style={{ marginTop: 40 }}>
      <Paper elevation={3} style={{ padding: 24 }}>
        {!role && !showMaids && (
          <Box textAlign="center">
            <Typography variant="h5" gutterBottom>Welcome to MAIDFINDER</Typography>
            <Box display="flex" justifyContent="center" gap={2} marginY={2}>
              <img src={process.env.PUBLIC_URL + "/assets/broom.png"} alt="Broom Icon" style={{ width: 60, height: 60 }} />
              <img src={process.env.PUBLIC_URL + "/assets/driver-cap.png"} alt="Driver Cap Icon" style={{ width: 60, height: 60 }} />
            </Box>
            <Button variant="contained" color="primary" fullWidth style={{ marginBottom: 16 }} onClick={() => setRole('maid')}>
              I am looking for work
            </Button>
            <Button variant="contained" color="secondary" fullWidth onClick={() => setRole('owner')}>
              I am looking for house help
            </Button>
            <Button variant="contained" color="success" fullWidth style={{ marginTop: 16 }} onClick={handleFindHouseHelp}>
              Find House Help
            </Button>
          </Box>
        )}
        {showMaids && !role && (
          <Box>
            <Typography variant="h6" gutterBottom>Available Maids</Typography>
            {maids.length === 0 ? (
              <Typography>No maids found.</Typography>
            ) : (
              maids.map((maid, idx) => (
                <Paper key={idx} style={{ margin: '12px 0', padding: 12 }}>
                  <Typography><b>Name:</b> {maid.name}</Typography>
                  <Typography><b>Phone:</b> {maid.phone}</Typography>
                  <Typography><b>Type of Work:</b> {maid.work_type}</Typography>
                  <Typography><b>Time:</b> {maid.time}</Typography>
                  <Typography><b>Location:</b> {maid.location}</Typography>
                  <Typography><b>Anywhere:</b> {maid.anywhere ? 'Yes' : 'No'}</Typography>
                  {maid.photo && <img src={`http://localhost:5000/uploads/${maid.photo}`} alt="maid" style={{ width: 80, height: 80, objectFit: 'cover', marginTop: 8 }} />}
                  <Button variant="outlined" color="primary" style={{ marginTop: 8 }}>Chat</Button>
                </Paper>
              ))
            )}
            <Button onClick={() => setShowMaids(false)} fullWidth style={{ marginTop: 16 }}>Back</Button>
          </Box>
        )}
        {role === 'maid' && <MaidForm onBack={() => setRole(null)} />}
        {role === 'owner' && <OwnerForm onBack={() => setRole(null)} />}
      </Paper>
    </Container>
  );
}

export default App;
import React, { useState } from 'react';
import { Button, Container, Typography, Box, Paper } from '@mui/material';
import MaidForm from './MaidForm';
import OwnerForm from './OwnerForm';
